exercises.starterCode:
// Presupuesto mensual de una cuenta de práctica. Le falta una alerta.
export const presupuesto = {
  nombre: "codeai-presupuesto-mensual",
  tipo: "COST",
  periodo: "MONTHLY",
  limite: { importe: "5", unidad: "USD" },
  alertas: [
    { tipo: "FORECASTED", operador: "GREATER_THAN", umbral: 100, tipoUmbral: "PERCENTAGE" },
  ],
};

solution.code:
export const presupuesto = {
  nombre: "codeai-presupuesto-mensual",
  tipo: "COST",
  periodo: "MONTHLY",
  limite: { importe: "5", unidad: "USD" },
  alertas: [
    { tipo: "ACTUAL", operador: "GREATER_THAN", umbral: 80, tipoUmbral: "PERCENTAGE" },
    { tipo: "FORECASTED", operador: "GREATER_THAN", umbral: 100, tipoUmbral: "PERCENTAGE" },
  ],
};

spec.code:
const real = presupuesto.alertas.find((alerta) => alerta.tipo === "ACTUAL");
assert.strictEqual(real?.tipoUmbral, "PERCENTAGE");
assert.strictEqual(real?.umbral, 80);

exercises.starterCode:
// Limpieza del presupuesto de la práctica: dos comandos y una conclusión.
export const limpieza = {
  borrado: "aws budgets delete-notification --budget-name codeai-presupuesto-mensual",
  comprobacion: "aws budgets describe-notifications-for-budget --budget-name codeai-presupuesto-mensual",
  recuperable: true,
};

solution.code:
export const limpieza = {
  borrado: "aws budgets delete-budget --account-id <ID> --budget-name codeai-presupuesto-mensual",
  comprobacion: "aws budgets describe-budgets --account-id <ID> --region us-east-1",
  recuperable: false,
};

spec.code:
assert.match(limpieza.borrado, /^aws budgets delete-budget /);
assert.match(limpieza.borrado, /--account-id \S+/);
assert.match(limpieza.borrado, /--budget-name codeai-presupuesto-mensual/);
